const stack=document.getElementById('work-stack'),list=document.getElementById('work-index-items'),summary=document.getElementById('work-summary'),info={number:document.getElementById('work-number')};
const cards=[],items=[];let active=-1,focused=-1;
projects.forEach((project,i)=>{const article=document.createElement('article');article.className='work-card';article.style.setProperty('--offset',`${[-11,14,-7,12,-9,8][i%6]}px`);article.style.setProperty('--tilt',`${[-.5,.4,.25,-.35,.45,-.25][i%6]}deg`);const button=document.createElement('button');button.type='button';button.setAttribute('aria-label',`Preview ${project.name}`);const img=new Image();img.src=project.image;img.onerror=()=>{if(img.src!==project.remote)img.src=project.remote};img.alt=project.name+' project cover';img.loading=i<3?'eager':'lazy';button.append(img);button.addEventListener('click',()=>openFocus(i));article.append(button);stack.append(article);cards.push(article);
 const item=document.createElement('button');item.className='work-index-item';item.type='button';item.innerHTML=`<small>${project.type}</small><strong>${project.name}</strong><em></em><p>${project.description}</p>`;item.addEventListener('click',()=>article.scrollIntoView({behavior:'smooth',block:'center'}));list.append(item);items.push(item)});
function setActive(i){if(i===active)return;active=i;const p=projects[i];summary.replaceChildren();const rows=[
  [p.name,p.description],
  [p.type,`${p.role.replace(/<br>/g,' · ')} · ${p.date}`],
  ['Recognition',p.awards.replace(/<br>/g,' · ')]
];rows.forEach(([title,body],index)=>{const row=document.createElement('div'),number=document.createElement('span'),name=document.createElement('strong'),description=document.createElement('span');row.className='work-summary-item'+(index===0?' active':'');number.className='summary-number';number.textContent=String(index+1).padStart(2,'0');name.textContent=title;description.className='summary-description';description.textContent=body;row.append(number,name,description);summary.append(row)});info.number.classList.add('changing');setTimeout(()=>{info.number.textContent=String(i+1).padStart(2,'0');info.number.classList.remove('changing')},120);items.forEach((item,j)=>{item.classList.toggle('active',i===j);if(i===j)item.setAttribute('aria-current','true');else item.removeAttribute('aria-current')});const target=items[i];const headerHeight=parseFloat(getComputedStyle(document.body).getPropertyValue('--work-header-height'))||188;const offset=(target.offsetTop+target.offsetHeight/2)-(innerHeight*.45-headerHeight);list.style.transform=`translateY(${-Math.max(0,offset)}px)`;document.getElementById('work-visit').onclick=()=>openFocus(i)}
let ticking=false;function update(){if(ticking)return;ticking=true;requestAnimationFrame(()=>{const center=innerHeight*.49;let closest=0,distance=Infinity;cards.forEach((card,i)=>{const rect=card.getBoundingClientRect(),d=Math.abs(rect.top+rect.height/2-center);if(d<distance){distance=d;closest=i}if(rect.bottom>-innerHeight*.2&&rect.top<innerHeight*1.2)card.classList.add('is-visible')});setActive(closest);ticking=false})}addEventListener('scroll',update,{passive:true});addEventListener('resize',update);update();
const focus=document.getElementById('work-focus'),detail=document.getElementById('work-detail');function openFocus(i){focused=i;const p=projects[i];focus.querySelector('img').src=p.image;focus.querySelector('img').onerror=e=>e.target.src=p.remote;focus.querySelector('.focus-caption span').textContent=`${p.type}  /  ${p.date}`;focus.querySelector('h2').textContent=p.name;focus.querySelector('p').textContent=p.description;focus.hidden=false;document.body.style.overflow='hidden';focus.querySelector('.focus-cover').onclick=e=>{if(e.target.closest('.focus-close'))return;openDetail(i)};focus.querySelector('.focus-caption button').onclick=()=>openDetail(i)}
function openDetail(i){const p=projects[i],next=projects[(i+1)%projects.length];focused=i;focus.hidden=true;detail.hidden=false;document.body.style.overflow='hidden';const extra=i===0?['SbcAb0YDNv6PLqpq5XAlze41BM.jpg','F487AXTxDP4zFhdlhNPN7uwgOIk.jpg','ykCmCfzhgrEyaaT99BSLyOoMNM.jpg'].map(name=>`<img src="https://framerusercontent.com/images/${name}?width=1500" alt="${p.name} project image" loading="lazy">`).join(''):`<img src="${p.image}" alt="${p.name} project image" loading="lazy">`;detail.querySelector('.detail-body').innerHTML=`<h1>${p.name}</h1><img class="detail-hero" src="${p.image}" alt="${p.name} cover"><div class="detail-description"><span>${p.type} / ${p.date}</span><p>${p.description}<br><br>${p.role.replace(/<br>/g, ' · ')}${i===0?'<br><br><a href="fromanother.html">View full case study ↗</a>':''}</p></div><div class="detail-gallery">${extra}</div><button class="detail-next" type="button"><span>Next project</span><img src="${next.image}" alt=""><strong>${next.name}</strong><span>View next →</span></button>`;detail.querySelector('.detail-next').onclick=()=>{detail.scrollTop=0;openDetail((i+1)%projects.length)};detail.scrollTop=0}
function closeOverlays(){focus.hidden=true;detail.hidden=true;document.body.style.overflow=''}focus.querySelector('.focus-close').onclick=closeOverlays;detail.querySelector('.detail-close').onclick=closeOverlays;addEventListener('keydown',e=>{if(e.key==='Escape')closeOverlays()});
document.getElementById('menuToggle').onclick=e=>{const nav=document.getElementById('menu');nav.classList.toggle('closed');e.currentTarget.setAttribute('aria-expanded',String(!nav.classList.contains('closed')))};document.getElementById('audioToggle').onclick=e=>{const on=e.currentTarget.getAttribute('aria-pressed')==='true';e.currentTarget.setAttribute('aria-pressed',String(!on));e.currentTarget.textContent=on?'Off —':'On —'};const clock=()=>document.getElementById('clock').textContent='HCMC, '+new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Ho_Chi_Minh',hour:'2-digit',minute:'2-digit'}).format(new Date());clock();setInterval(clock,60000);
